-- dws metrics --
CREATE OR REPLACE TEMPORARY VIEW dws_global_search_${grass_region_without_quote} AS
SELECT
    user_id
    ,item_id
    ,target_type AS card_type 
    ,ARRAY(COALESCE(CAST(is_ads AS STRING), 'false'), '__ALL__') AS is_ads_group
    ,IF(CAST(location AS INT) <= 99, location, 'NA') AS location
    ,ARRAY(IF(item_id IS NOT NULL, 'true', 'false'), '__ALL__') AS with_item_group
    ,IF(search_entrance IS NOT NULL AND TRIM(LOWER(search_entrance)) != '', TRIM(LOWER(search_entrance)), 'NA') AS search_entrance
    ,IF(CAST(location AS INT) <= 3, '0~3', 'false') AS is_0to3_location
    ,IF(CAST(location AS INT) <= 9, '0~9', 'false') AS is_0to9_location
    ,IF(CAST(location AS INT) <= 19, '0~19', 'false') AS is_0to19_location
    ,IF(search_entrance IN ('live_search', 'video_search', 'content_mix_search'), 'all_content_search', 'not_content_search') AS is_content_entrance
    ,'item+video+live' AS is_item_video_live_card
    ,imp_cnt
    ,click_cnt
    ,ppv_cnt
    ,cart_cnt
    ,order_cnt
    ,gmv
    ,pc2_gmv
FROM
    srdi_mart.dws_sr_data_warehouse_platform_user_item_keyword_benchmark_1d
WHERE
    local_date = ${local_date}
    AND grass_region = ${grass_region}
    AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
    AND page_section IS NULL 
    AND target_type IN ('item', 'video', 'livestream')
    AND user_id > 0
UNION ALL
SELECT
    user_id
    ,item_id
    ,CASE
        WHEN page_type IN ('global_search','search_in_pdp','search_prefill') AND page_section IS NULL AND target_type IN ('ai_minifeed_card') THEN 'ai_minifeed_card'
        WHEN page_type = 'video' and page_section IS NULL AND target_type IN ('video_product_impression', 'video_product_click','atc_click','buynow_click') AND minifeed_inner_card_type = 'item_card' THEN 'ai_minifeed_inner_item'
        WHEN page_type = 'video' and page_section IS NULL AND target_type IN ('video_product_impression', 'video_product_click','atc_click','buynow_click') AND minifeed_inner_card_type = 'video_card' THEN 'ai_minifeed_inner_video'
        WHEN page_type in ('global_search','search_in_pdp','search_prefill') AND page_section is null AND target_type IN  ('ai_topic_card')  THEN 'ai_topic_card'
        WHEN page_type = 'ai_topic_landing' and page_section = 'topic_result' and target_type in ('item','add_to_cart_button') THEN 'ai_topic_inner_item'
        ELSE 'unknown'
    END AS card_type 
    ,ARRAY(COALESCE(CAST(is_ads AS STRING), 'false'), '__ALL__') AS is_ads_group
    ,CASE 
        WHEN page_type IN ('global_search','search_in_pdp','search_prefill') AND srp_location <= 99 THEN CAST(srp_location AS STRING)
        WHEN page_type NOT IN ('global_search','search_in_pdp','search_prefill') AND inner_location <= 99 THEN CAST(inner_location AS STRING)
        ELSE 'NA'
    END AS location
    ,ARRAY(IF(item_id IS NOT NULL, 'true', 'false'), '__ALL__') AS with_item_group
    ,'NA' AS search_entrance
    ,CASE 
        WHEN page_type IN ('global_search','search_in_pdp','search_prefill') AND srp_location <= 3 THEN '0~3'
        WHEN page_type NOT IN ('global_search','search_in_pdp','search_prefill') AND inner_location <= 3 THEN '0~3'
        ELSE 'false'
    END AS is_0to3_location
    ,CASE 
        WHEN page_type IN ('global_search','search_in_pdp','search_prefill') AND srp_location <= 9 THEN '0~9'
        WHEN page_type NOT IN ('global_search','search_in_pdp','search_prefill') AND inner_location <= 9 THEN '0~9'
        ELSE 'false'
    END AS is_0to9_location
    ,CASE 
        WHEN page_type IN ('global_search','search_in_pdp','search_prefill') AND srp_location <= 19 THEN '0~19'
        WHEN page_type NOT IN ('global_search','search_in_pdp','search_prefill') AND inner_location <= 19 THEN '0~19'
        ELSE 'false'
    END AS is_0to19_location
    ,'not_content_search' AS is_content_entrance
    ,'false' AS is_item_video_live_card
    ,imp_cnt
    ,click_cnt
    ,NULL AS ppv_cnt
    ,NULL AS cart_cnt
    ,order_cnt
    ,gmv
    ,pc2_gmv
FROM
    srdi_mart.dws_sr_data_warehouse_ai_search_wide_metrics_1d
WHERE
    local_date = ${local_date}
    AND grass_region = ${grass_region}
    AND (
        (page_type IN ('global_search','search_in_pdp','search_prefill') AND page_section IS NULL AND target_type IN ('ai_minifeed_card'))
        OR (page_type = 'video' and page_section IS NULL AND target_type IN ('video_product_impression', 'video_product_click','atc_click','buynow_click'))
        OR (page_type in ('global_search','search_in_pdp','search_prefill') AND page_section is null AND target_type IN  ('ai_topic_card'))
        OR (page_type = 'ai_topic_landing' and page_section = 'topic_result' and target_type in ('item','add_to_cart_button'))
    )
    AND user_id > 0;

--sql_divide_splitter--

CACHE TABLE dwm_search_metric_flatten_${grass_region_without_quote} AS
SELECT
    user_id
    ,FILTER(ARRAY(card_type, is_item_video_live_card), x -> x != 'false') AS card_type_group
