    ,SUM(cart_cnt) AS cart_cnt
    ,IF(SUM(cart_cnt) > 0, 1, 0) AS cart_uu
    ,SUM(order_cnt) AS order_cnt
    ,IF(SUM(order_cnt) > 0, 1, 0) AS order_uu
    ,SUM(gmv) AS gmv
    ,SUM(pc2_gmv) AS pc2_gmv
