CREATE OR REPLACE TEMPORARY VIEW dwm_search_exp_metric_${grass_region_without_quote} AS
SELECT 
    card_type
    ,is_ads
    ,location
    ,with_item
    ,search_entrance
    ,exp_sum(b.exp_group_ids, ARRAY(imp_cnt, imp_uu, click_cnt, click_uu, ppv_cnt
        ,ppv_uu, cart_cnt, cart_uu, order_cnt, order_uu, gmv, pc2_gmv)
    ) AS exp_metrics
