CREATE OR REPLACE TEMPORARY VIEW dws_search_exp_metric_${grass_region_without_quote} AS
SELECT
    e.exp_group_id AS exp_group_id
    ,card_type
    ,is_ads
    ,location
    ,with_item
    ,search_entrance
    ,CAST(e.fields[0] AS BIGINT) AS imp_cnt
    ,CAST(e.fields[1] AS BIGINT) AS imp_uu
    ,CAST(e.fields[2] AS BIGINT) AS click_cnt
    ,CAST(e.fields[3] AS BIGINT) AS click_uu
    ,CAST(e.fields[4] AS BIGINT) AS ppv_cnt
    ,CAST(e.fields[5] AS BIGINT) AS ppv_uu
    ,CAST(e.fields[6] AS BIGINT) AS cart_cnt
    ,CAST(e.fields[7] AS BIGINT) AS cart_uu
    ,e.fields[8] AS order_cnt
    ,CAST(e.fields[9] AS BIGINT) AS order_uu
    ,e.fields[10] AS gmv
    ,e.fields[11] AS pc2_gmv
