-- all_ads_session_cnt & search_session_cnt metrics --
CREATE TEMPORARY VIEW dwd_search_session_count_${grass_region_without_quote} AS
SELECT
    user_id
    ,IF(location <= 3, '0~3', 'false') AS is_0to3_location
    ,IF(location <= 9, '0~9', 'false') AS is_0to9_location
    ,IF(location <= 19, '0~19', 'false') AS is_0to19_location
    ,IF(search_entrance IS NOT NULL AND TRIM(LOWER(search_entrance)) != '', TRIM(LOWER(search_entrance)), 'NA') AS search_entrance
    ,IF(search_entrance IN ('live_search', 'video_search', 'content_mix_search'), 'all_content_search', 'not_content_search') AS is_content_entrance
    ,search_session_id
    ,SUM(IF(is_ads = true, 1, 0)) AS ads_imp_cnt
    ,SUM(1) AS imp_cnt
FROM
    srdi_mart.dwd_sr_data_warehouse_platform
WHERE
    local_date = ${local_date}
    AND grass_region = ${grass_region}
    AND user_id > 0
    AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
    AND page_section IS NULL 
    AND target_type IN ('item', 'video', 'livestream')
    AND search_session_id IS NOT NULL
    AND operation = 'impression'
GROUP BY
    1,2,3,4,5,6,7;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwm_search_session_count_${grass_region_without_quote} AS
SELECT
    user_id
    ,search_entrance_group AS search_entrance
    ,location_group AS location
    ,search_session_id
    ,SUM(ads_imp_cnt) as ads_imp_cnt
    ,SUM(imp_cnt) as imp_cnt
FROM
    dwd_search_session_count_${grass_region_without_quote}
LATERAL VIEW
    EXPLODE(ARRAY(search_entrance, is_content_entrance, '__ALL__')) AS search_entrance_group
LATERAL VIEW
    EXPLODE(FILTER(ARRAY(is_0to3_location, is_0to9_location, is_0to19_location, '__ALL__'), x -> x != 'false')) AS location_group
GROUP BY
    1,2,3,4;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_search_session_count_${grass_region_without_quote} AS
SELECT
    exp_group_id
    ,search_entrance
    ,location
    ,SUM(IF(imp_cnt = ads_imp_cnt, 1, 0)) AS all_ads_session_cnt
    ,SUM(1) AS search_session_cnt
FROM
    dwm_search_session_count_${grass_region_without_quote} a
JOIN
    user_exp_mapping_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
GROUP BY
    1,2,3;

