CREATE OR REPLACE TEMPORARY VIEW search_scene_${grass_region_without_quote} AS
SELECT
    user_id 
    ,target_type AS card_type
    ,CASE 
        WHEN location <= 99 THEN CAST(location AS STRING)
        ELSE 'NA'
    END AS location
    ,IF(item_id IS NOT NULL, 'true', 'false') AS with_item
    ,IF(search_entrance IS NOT NULL AND TRIM(LOWER(search_entrance)) != '', TRIM(LOWER(search_entrance)), 'NA') AS search_entrance
    ,SUM(imp_cnt) AS imp_cnt
FROM 
    srdi_mart.dws_sr_data_warehouse_platform_user_item_keyword_benchmark_1d
WHERE
    local_date = ${local_date}
    AND grass_region = ${grass_region}
    AND page_type IN (
        'global_search'
        ,'search_in_mall'
        ,'search_in_microsite'
        ,'search_in_main_category'
        ,'collection'
        ,'search_in_others'
        ,'search_in_collection'
        ,'search_in_product_attribute'
        ,'main_category_browsing'
        ,'search_in_voucher'
        ,'search_in_subcategory'
        ,'search_in_pdp'
        ,'search_prefill'
        ,'search'
    )
    AND original_page_type = 'search'
    AND page_section IS NULL 
    AND target_type IN ('item', 'video', 'livestream','related_search')
GROUP BY
    1,2,3,4,5;

