CREATE OR REPLACE TEMPORARY VIEW exchange_rate_${grass_region_without_quote} AS
SELECT
    grass_date
    ,grass_region
    ,exchange_rate
FROM
    mp_order.dim_exchange_rate__reg_s0_live
WHERE
    grass_date =  ${local_date}
    AND grass_region = ${grass_region};

--sql_divide_splitter--

CREATE OR REPLACE TEMPORARY VIEW dws_ads_raw_${grass_region_without_quote} AS
SELECT
    user_id
    ,IF(item_id IS NOT NULL, 'true', 'false') AS with_item
    ,CASE 
        WHEN location <= 99 THEN CAST(location AS STRING)
        ELSE 'NA'
    END AS location
    ,IF(target_type IS NOT NULL, target_type, 'NA') AS card_type
    ,IF(search_entrance IS NOT NULL AND TRIM(LOWER(search_entrance)) != '', TRIM(LOWER(search_entrance)), 'NA') AS search_entrance
    --ads imp, click
    ,SUM(impression_cnt) as ads_impression_cnt
    ,SUM(click_cnt) as ads_click_cnt
    --broad 口径 ads gmv
    ,SUM(broad_order_cnt) as ads_broad_order
    ,SUM(broad_gmv_amt_local) as ads_broad_gmv_local
    ,SUM(broad_gmv_amt_local / CAST(exchange_rate AS DOUBLE)) AS ads_broad_gmv_usd
    --narrow 口径 ads gmv
    ,SUM(order_cnt) as ads_order
    ,SUM(ads_order_gmv_local) as ads_gmv_local
    ,SUM(ads_order_gmv_usd) as ads_gmv_usd
    --ads revenue
    ,SUM(expenditure_amt_local) as ads_revenue_local
    ,SUM(expenditure_amt_usd) as ads_revenue_usd
FROM
    mp_paidads.dwd_advertise_performance_di__reg_s0_live a
LEFT JOIN
    exchange_rate_${grass_region_without_quote} c
ON
    a.grass_date = c.grass_date
    AND a.grass_region = c.grass_region
WHERE
    a.grass_date = ${local_date}
    AND a.grass_region = ${grass_region}
    AND a.tz_type = 'local'
    AND a.entrance = 1 --global search
    AND (a.target_type IS NULL OR a.target_type IN ('item', 'video', 'livestream'))
GROUP BY
    1,2,3,4,5;

--sql_divide_splitter--

CREATE OR REPLACE TEMPORARY VIEW dwd_ads_performance_raw_${grass_region_without_quote} AS 
SELECT
    exp_group_id
    ,with_item
    ,location
    ,card_type
    ,search_entrance
    --ads imp, click
    ,SUM(ads_impression_cnt) as ads_impression_cnt
    ,SUM(ads_click_cnt) as ads_click_cnt
    --broad 口径 ads gmv
    ,SUM(ads_broad_order) as ads_broad_order
    ,SUM(ads_broad_gmv_local) as ads_broad_gmv_local
    ,SUM(ads_broad_gmv_usd) AS ads_broad_gmv_usd
    --narrow 口径 ads gmv
    ,SUM(ads_order) as ads_order
    ,SUM(ads_gmv_local) as ads_gmv_local
    ,SUM(ads_gmv_usd) as ads_gmv_usd
    --ads revenue
    ,SUM(ads_revenue_local) as ads_revenue_local
    ,SUM(ads_revenue_usd) as ads_revenue_usd
FROM
    dws_ads_raw_${grass_region_without_quote} a
JOIN
    user_exp_mapping_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
GROUP BY
    1,2,3,4,5;

