CREATE OR REPLACE TEMPORARY VIEW dws_ads_metrics_${grass_region_without_quote} AS
SELECT
    COALESCE(a.exp_group_id, b.exp_group_id, c.exp_group_id) AS exp_group_id
    ,COALESCE(a.card_type, b.card_type, c.card_type, 'NA') AS card_type
    ,COALESCE(a.location, b.location, c.location, 'NA') AS location
    ,COALESCE(a.with_item, b.with_item, c.with_item, 'NA') AS with_item
    ,COALESCE(a.search_entrance, b.search_entrance, c.search_entrance, 'NA') AS search_entrance

    ,SUM(COALESCE(ads_item_order, 0)) AS ads_item_order
    ,SUM(COALESCE(ads_item_gmv, 0)) AS ads_item_gmv
    ,SUM(COALESCE(ads_item_pc2_gmv, 0)) AS ads_item_pc2_gmv

    ,SUM(COALESCE(ads_impression_cnt, 0)) AS ads_impression_cnt
    ,SUM(COALESCE(ads_click_cnt, 0)) AS ads_click_cnt
    ,SUM(COALESCE(ads_broad_order, 0)) AS ads_broad_order
    ,SUM(COALESCE(ads_broad_gmv_local, 0)) AS ads_broad_gmv_local
    ,SUM(COALESCE(ads_broad_gmv_usd, 0)) AS ads_broad_gmv_usd
    ,SUM(COALESCE(ads_order, 0)) AS ads_order
    ,SUM(COALESCE(ads_gmv_local, 0)) AS ads_gmv_local
    ,SUM(COALESCE(ads_gmv_usd, 0)) AS ads_gmv_usd
    ,SUM(COALESCE(ads_revenue_local, 0)) AS ads_revenue_local
    ,SUM(COALESCE(ads_revenue_usd, 0)) AS ads_revenue_usd

    ,SUM(COALESCE(imp_cnt, 0)) AS ads_load_denom_imp_cnt
FROM
    dwd_ads_performance_raw_${grass_region_without_quote} a
FULL JOIN
    dwd_ads_order_metrics_${grass_region_without_quote} b
ON
    a.exp_group_id = b.exp_group_id
    AND a.card_type = b.card_type
    AND a.location = b.location
    AND a.with_item = b.with_item
    AND a.search_entrance = b.search_entrance
FULL JOIN
    ads_load_denominator_${grass_region_without_quote} c
ON
    COALESCE(a.exp_group_id, b.exp_group_id) = c.exp_group_id
    AND COALESCE(a.card_type, b.card_type) = c.card_type
    AND COALESCE(a.location, b.location) = c.location
    AND COALESCE(a.with_item, b.with_item) = c.with_item
    AND COALESCE(a.search_entrance, b.search_entrance) = c.search_entrance
GROUP BY
    1,2,3,4,5;

--sql_divide_splitter--

CREATE OR REPLACE TEMPORARY VIEW dws_ads_metrics_flattened_${grass_region_without_quote} AS
SELECT
    exp_group_id
    ,card_type
    ,IF(card_type IN ('item', 'video', 'livestream'), 'item+video+live', 'false') AS is_item_video_live_card
    ,location
    ,IF(CAST(location AS INT) BETWEEN 0 AND 3, '0~3', 'false') AS is_0to3_location
    ,IF(CAST(location AS INT) BETWEEN 0 AND 9, '0~9', 'false') AS is_0to9_location
    ,IF(CAST(location AS INT) BETWEEN 0 AND 19, '0~19', 'false') AS is_0to19_location
    ,with_item
    ,search_entrance
    ,IF(search_entrance IN ('live_search', 'video_search', 'content_mix_search'), 'all_content_search', 'not_content_search') AS is_content_entrance
    ,ads_item_order
    ,ads_item_gmv
    ,ads_item_pc2_gmv
    ,ads_impression_cnt
    ,ads_click_cnt
    ,ads_broad_order
    ,ads_broad_gmv_local
    ,ads_broad_gmv_usd
    ,ads_order
    ,ads_gmv_local
    ,ads_gmv_usd
    ,ads_revenue_local
    ,ads_revenue_usd
    ,ads_load_denom_imp_cnt
FROM
    dws_ads_metrics_${grass_region_without_quote};

--sql_divide_splitter--

CREATE OR REPLACE TEMPORARY VIEW dws_ads_metrics_process_${grass_region_without_quote} AS
SELECT
    *
    ,ARRAY(with_item, '__ALL__') AS with_item_group
    ,FILTER(ARRAY(card_type, is_item_video_live_card), x -> x != 'false') AS card_type_group
    ,FILTER(ARRAY(location, is_0to3_location, is_0to9_location, is_0to19_location, '__ALL__'), x -> x != 'false') AS location_group
    ,ARRAY(search_entrance, is_content_entrance, '__ALL__') AS search_entrance_group
FROM 
    dws_ads_metrics_flattened_${grass_region_without_quote};

--sql_divide_splitter--

CREATE OR REPLACE TEMPORARY VIEW dws_ads_metrics_grouped_${grass_region_without_quote} AS
SELECT
    exp_group_id
    ,card_type_m AS card_type
    ,location_m AS location
    ,with_item_m AS with_item
    ,search_entrance_m AS search_entrance
    ,SUM(ads_item_order) AS ads_item_order
    ,SUM(ads_item_gmv) AS ads_item_gmv
    ,SUM(ads_item_pc2_gmv) AS ads_item_pc2_gmv
    ,SUM(ads_impression_cnt) AS ads_impression_cnt
    ,SUM(ads_click_cnt) AS ads_click_cnt
    ,SUM(ads_broad_order) AS ads_broad_order
    ,SUM(ads_broad_gmv_local) AS ads_broad_gmv_local
    ,SUM(ads_broad_gmv_usd) AS ads_broad_gmv_usd
    ,SUM(ads_order) AS ads_order
    ,SUM(ads_gmv_local) AS ads_gmv_local
    ,SUM(ads_gmv_usd) AS ads_gmv_usd
    ,SUM(ads_revenue_local) AS ads_revenue_local
    ,SUM(ads_revenue_usd) AS ads_revenue_usd
    ,SUM(ads_load_denom_imp_cnt) AS ads_load_denom_imp_cnt
    ,CAST(COALESCE(SUM(ads_impression_cnt), 0) AS DOUBLE) / CAST(SUM(ads_load_denom_imp_cnt) AS DOUBLE) AS ads_load
FROM
    dws_ads_metrics_process_${grass_region_without_quote}
    LATERAL VIEW EXPLODE(location_group) AS location_m
    LATERAL VIEW EXPLODE(search_entrance_group) AS search_entrance_m
    LATERAL VIEW EXPLODE(card_type_group) AS card_type_m
    LATERAL VIEW EXPLODE(with_item_group) AS with_item_m
GROUP BY
    1,2,3,4,5;

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_abtest_location_metrics_1d
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
)
SELECT
    scene_id
    ,scene_name
    ,layer_id
    ,layer_name
    ,experiment_id
    ,experiment_name
    ,a.exp_group_id
    ,exp_group_name
    ,a.card_type
    ,is_ads
    ,a.location

    ,exp_group_uu
    ,imp_cnt
    ,imp_uu
    ,click_cnt
    ,click_uu
    ,ppv_cnt
    ,ppv_uu
    ,cart_cnt
    ,cart_uu
    ,order_cnt
    ,order_uu
    ,gmv
    ,pc2_gmv

    ,ads_item_order
    ,ads_item_gmv
    ,ads_item_pc2_gmv

    ,ads_impression_cnt
    ,ads_click_cnt
    ,ads_broad_order
    ,ads_broad_gmv_local
    ,ads_broad_gmv_usd
    ,ads_order
    ,ads_gmv_local
    ,ads_gmv_usd
    ,ads_revenue_local
    ,ads_revenue_usd

    ,a.with_item
    ,a.search_entrance
    ,ads_load

    ,all_ads_session_cnt
    ,search_session_cnt
    ,max_imp_inner_location_avg
    ,max_imp_inner_location_p50
    ,max_imp_inner_location_p90
FROM 
    dws_search_exp_metric_${grass_region_without_quote} a
LEFT JOIN
    dws_ads_metrics_grouped_${grass_region_without_quote} b
ON
    a.exp_group_id = b.exp_group_id
    AND a.location = b.location
    AND a.is_ads IN ('__ALL__', 'true')
    AND a.card_type = b.card_type
    AND a.search_entrance = b.search_entrance
    AND a.with_item = b.with_item
LEFT JOIN
    dws_exp_uu_${grass_region_without_quote} c 
ON
    a.exp_group_id = c.exp_group_id
LEFT JOIN
    dim_exp_${grass_region_without_quote} d
ON
    a.exp_group_id = d.exp_group_id
LEFT JOIN
    dws_search_session_count_${grass_region_without_quote} e
ON
    a.exp_group_id = e.exp_group_id
    AND a.location = e.location
    AND a.is_ads = '__ALL__'
    AND a.card_type = 'item+video+live'
    AND a.search_entrance = e.search_entrance
    AND a.with_item = '__ALL__'
LEFT JOIN
    ai_minifeed_card_max_location_percentile_${grass_region_without_quote} f
ON
    a.exp_group_id = f.exp_group_id
    AND a.location = '__ALL__'
    AND a.is_ads = '__ALL__'
    AND a.card_type = 'ai_minifeed_card'
    AND a.search_entrance = '__ALL__'
    AND a.with_item = '__ALL__';
